func (inst *InitializeWithPermission) findFindObservationStateAddress(poolState ag_solanago.PublicKey, knownBumpSeed uint8) (pda ag_solanago.PublicKey, bumpSeed uint8, err error) {
	var seeds [][]byte
	// const: observation
	seeds = append(seeds, []byte{byte(0x6f), byte(0x62), byte(0x73), byte(0x65), byte(0x72), byte(0x76), byte(0x61), byte(0x74), byte(0x69), byte(0x6f), byte(0x6e)})
	// path: poolState
	seeds = append(seeds, poolState.Bytes())

	if knownBumpSeed != 0 {
		seeds = append(seeds, []byte{byte(bumpSeed)})
		pda, err = ag_solanago.CreateProgramAddress(seeds, ProgramID)
	} else {
		pda, bumpSeed, err = ag_solanago.FindProgramAddress(seeds, ProgramID)
	}
	return
}

